def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if not alive:
        return float(min(budget, 18.0))

    highest_prev_bid = 0.0
    cindy_prev_bid = 0.0
    pressure = 0
    rich_alive = 0

    for agent_id, opp in alive:
        if opp.get('budget', 0) >= 200:
            rich_alive += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            if bid > highest_prev_bid:
                highest_prev_bid = bid
            if bid >= 75:
                pressure += 2
            elif bid >= 45:
                pressure += 1
        if agent_id == 'Cindy' and bid is not None:
            cindy_prev_bid = bid

    urgent = hp <= 3 or no_water >= 2
    semi_urgent = hp <= 5 or no_water >= 1

    if urgent:
        target = max(88.0, cindy_prev_bid + 2.5, highest_prev_bid + 1.5)
        if budget < target:
            target = budget
        return float(max(0.0, min(budget, target)))

    if semi_urgent:
        if cindy_prev_bid >= 85:
            target = 89.0
        elif cindy_prev_bid >= 70:
            target = cindy_prev_bid + 2.0
        else:
            target = max(52.0, highest_prev_bid + 1.0)
        return float(max(0.0, min(budget, target)))

    if rich_alive <= 1 and cindy_prev_bid >= 80:
        return float(max(0.0, min(budget, 12.0)))

    if pressure == 0:
        base = 24.0 if day <= 3 else 18.0
        return float(max(0.0, min(budget, base)))

    if cindy_prev_bid >= 90:
        return float(max(0.0, min(budget, 10.0)))

    if cindy_prev_bid >= 75:
        target = 46.0 if day < 8 else 58.0
        return float(max(0.0, min(budget, target)))

    target = max(28.0, min(60.0, highest_prev_bid + 1.5))
    return float(max(0.0, min(budget, target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    # Identify alive opponents
    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((oid, o))

    # If alone, conserve
    if not alive:
        return float(min(my_status['budget'], DAILY_SALARY * 0.35))

    # Use yesterday's immediate trace bids to infer aggression
    prev_bids = []
    prev_hp_after = []
    for oid, o in alive:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass
        hpa = prev.get('hp_after', None)
        if hpa is not None:
            try:
                prev_hp_after.append(float(hpa))
            except Exception:
                pass

    # Defaults
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev_bid
    else:
        highest_prev_bid = 0.0
        second_prev_bid = 0.0

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))

    # Determine target bid band based on opponent pressure
    # Cindy likely highest; if highest_prev_bid is near salary, pressure is high.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # High pressure: pay enough to secure water if I'm not healthy
        if my_hp <= 2.5:
            target = DAILY_SALARY * 0.95
        elif my_hp <= 4.5:
            target = max(DAILY_SALARY * 0.75, second_prev_bid + 5.0)
        else:
            target = max(DAILY_SALARY * 0.55, second_prev_bid + 2.5)
    elif highest_prev_bid >= DAILY_SALARY * 0.55:
        # Moderate pressure: bid slightly above typical winner
        target = max(DAILY_SALARY * 0.50, second_prev_bid + 1.5)
    else:
        # Low pressure: conserve
        target = DAILY_SALARY * 0.45

    # Adjust for supply: if supply is low, competition for scarce water tends to be higher
    # Normalize supply to [0,1]
    if MAX_SUPPLY > MIN_SUPPLY:
        s_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        s_norm = 0.5
    s_norm = max(0.0, min(1.0, float(s_norm)))

    # If supply is scarce, add a small premium; if abundant, reduce
    target = target * (0.92 + 0.16 * s_norm)

    # Never bid more than budget; also avoid extreme bids when budget is low
    # Keep a floor to ensure we aren't always losing when pressured
    if my_budget <= 0.0:
        return 0.0

    # If budget is too small, spend a fraction based on HP
    if my_budget < DAILY_SALARY * 0.6:
        if my_hp <= 2.5:
            cap_frac = 0.95
        elif my_hp <= 4.5:
            cap_frac = 0.75
        else:
            cap_frac = 0.55
        bid = my_budget * cap_frac
    else:
        bid = min(my_budget, target)

    # Ensure bid is non-negative float
    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1) 

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    current_bid = DAILY_SALARY * 0.5 

    if my_status['hp'] <= 2: 
        current_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4: 
        current_bid = DAILY_SALARY * 0.75

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2 and my_status['budget'] > DAILY_SALARY * 1.5:
        current_bid = max(current_bid, DAILY_SALARY * 0.85)

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3: 
                current_bid = max(current_bid, DAILY_SALARY * 0.6) 
            else: 
                current_bid = max(current_bid, highest_prev_bid + 5)
        elif highest_prev_bid >= DAILY_SALARY * 0.5:
            current_bid = max(current_bid, highest_prev_bid + 2)
        else:
            water_units_available = int(day_context['supply'] // WATER_REQ)
            total_players = len(alive_opponents) + 1
            if water_units_available < total_players and water_units_available > 0: 
                current_bid = max(current_bid, highest_prev_bid + 10)
            else:
                current_bid = max(current_bid, highest_prev_bid * 1.1)

    final_bid = min(my_status['budget'], current_bid)

    return max(0.0, final_bid)

